	KEY_GUILD_WAITING = "%d no vistos por tu /who",
	KEY_GUILD_WAIT_TIP = "Nombrados solo por el censo, no vistos en ella por tu /who: %s. No hay clave para ellos hasta que los vea allí (una fila del censo es la palabra de cualquiera).",
	KEY_HAND_OUT = "Entregarla a las hermandades marcadas (%d)",
	KEY_HAND_OUT_CONFIRM = "¿Susurrar la nueva clave a los Señores y Capitanes conectados de las %s hermandades marcadas, los que tu /who vio en ellas? Cada uno la pasa a toda su hermandad por el chat de hermandad.",
	KEY_MOVE_CONFIRM = "¿Pasar ya a la nueva clave? Tu hermandad te sigue. Los Señores y Capitanes que entren más tarde ya no la reciben por susurro.",
	KEY_MOVE_NOW = "Pasar ya a la nueva clave (en %d min de todos modos)",
	KEY_NO_GUILDS = "No hay ningún Señor ni Capitán de otra hermandad conectado que confirme el censo.",
	KEY_OFFICERS_ONLY = "Solo los oficiales de una hermandad de Olympus pueden poner la clave de reino.",
	KEY_PICK_HINT = "Elige quién la recibe. Las hermandades que vio tu /who están marcadas; una fila del censo por sí sola es la palabra de cualquiera (dos personajes pueden inventarse una hermandad y sus Señores, o hacerse pasar por los de una hermandad real). Solo los Señores y Capitanes que tu propio /who vio en su hermandad reciben el susurro. Cualquiera en una hermandad que la recibe la tiene: haz clic en una hermandad para cambiarlo.",
	KEY_ROTATE = "Renovar la clave del ejército",
	KEY_ROTATED = "La nueva clave del ejército va por susurro a los Señores y Capitanes conectados de las hermandades que elegiste, los que tu /who vio en ellas. Pasas a ella con tu hermandad en %d minutos, o antes desde el Trono.",
	KEY_ROTATED_AGO = "Renovada %s: %d Señores y Capitanes la tienen (%d hermandades)",
	KEY_ROTATED_TAKEN = "La clave del canal del ejército cambió (la nueva clave del Rey, o la de tus oficiales): entrando en el nuevo canal.",
	KEY_ROTATE_BUSY = "Hay una clave nueva esperando en el Trono: antes, entrégala y pasa a ella, o descártala.",
	KEY_ROTATE_CONFIRM = "¿Renovar la clave del ejército? Tu addon crea una nueva (nadie la ve, tú tampoco). Luego eliges en el Trono qué hermandades la reciben, y no se envía nada antes de que la entregues: va por susurro a sus Señores y Capitanes conectados que tu /who vio en ellas, y cada uno la pasa a su hermandad por el chat de hermandad. Pasas a ella con tu hermandad %s minutos después de entregarla (o cuando lo digas). Un Señor o Capitán que entre mientras tanto no recibe nada hasta que tu /who lo vea en su hermandad (haz clic en la línea de /who del Trono). Una hermandad sin ningún oficial conectado para entonces se queda en el canal antiguo hasta que uno de sus oficiales escriba la clave a mano.",
	KEY_ROTATE_DROP = "Descartar esta clave nueva (no se envió nada)",
	KEY_ROTATE_DROPPED = "Clave nueva descartada: no se envió nada.",
	KEY_ROTATE_ONLY_KING = "Solo el Rey o su Senescal renuevan la clave del ejército. Los oficiales siguen sellando el canal de su propia hermandad con /oly key.",
	KEY_ROTATE_READY = "Se creó una nueva clave del ejército (nadie la ve). Elige en el Trono qué hermandades la reciben y luego entrégala: no se envía nada antes.",
	KEY_ROTATE_TIP = "Una clave nueva, creada por tu addon y nunca mostrada (tampoco en tu directo). Eliges qué hermandades la reciben (las que vio tu /who están marcadas); va por susurro a sus Señores y Capitanes conectados que tu /who vio en ellas (una fila del censo por sí sola es la palabra de cualquiera), que la pasan a sus hermandades por el chat de hermandad: nunca viaja por el canal de Olympus. Quien tenga la clave antigua fuera de las hermandades que elijas se queda atrás en el canal antiguo; cualquiera en una hermandad que la recibe también la tiene.",
	KEY_ROTATE_TITLE = "La clave del ejército",
	KEY_ROTATING = "Entregada a %d Señores y Capitanes, %d la tienen (%d hermandades)",
	KEY_ROTATION_MOVED = "Ya estás con tu hermandad en la nueva clave del ejército: el canal antiguo queda atrás.",
	KEY_SET = "Clave de reino puesta: el canal de Olympus está ahora sellado y tus compañeros de hermandad reciben la clave solos.",
	KEY_TOO_SHORT = "La clave necesita al menos 6 caracteres.",
	KEY_WHO_CONFIRM = "Buscarlos con /who: %d Señores y Capitanes elegidos aún no vistos en su hermandad (una búsqueda por clic)",
	KEY_WHO_GAMEPAD = "Con la interfaz de mando tu /who busca en cada hermandad elegida (una por clic, nunca un nombre), y de nuevo en una hermandad un minuto después de su última búsqueda: los Señores y Capitanes que lista en su hermandad reciben la clave.",
	KING = "Rey",
	KING_ARROW_DENIED = "Solo el Rey, el Alto Consejo actual o un moderador autorizado de La Guardia pueden cambiar la flecha del Rey.",
	KING_ARROW_DISABLED = "La flecha del minimapa hacia el Rey está desactivada. Su corona y sus opciones de compartir no han cambiado.",
	KING_ARROW_ENABLED = "La flecha del minimapa hacia el Rey está activada. Su corona y sus opciones de compartir no han cambiado.",
	KING_ARROW_GLOBAL_TIP = "Activa o desactiva solo la flecha direccional del minimapa para Olympus. Nunca cambia la corona, el consentimiento de ubicación del Rey, el compartir capas ni otros marcadores del mapa.",
	KING_ARROW_GUILD_TIP = "Activa o desactiva solo la flecha direccional del minimapa para tu hermandad. Nunca cambia la corona, el consentimiento de ubicación del Rey, el compartir capas ni otros marcadores del mapa.",
	KING_ARROW_OFF = "Desactivada",
	KING_ARROW_ON = "Activada",
	KING_ARROW_STATUS = "Flecha del minimapa hacia el Rey: %s.",
	KING_ARROW_TITLE = "Flecha del minimapa hacia el Rey",
	KING_ARROW_USAGE = "Uso: /oly kingarrow on|off",
	LAYERS_HINT = "Aún no se ha visto ninguna capa: selecciona o pasa el ratón por encima de cualquier PNJ.",
	LAYERS_IN = "Capas en %s",
	LAYER_COUNT = "~%d con Olympus",
	LAYER_EXPERIMENTAL = "Experimental: una capa lleva el nombre del miembro de Olympus de mayor rango que está en ella.",
	LAYER_OF = "Capa de %s",
	LAYER_UNKNOWN = "Capa desconocida",
	LAYER_YOU = "Estás aquí",
	LETTERS_ALL = "Todas las cartas",
	LETTERS_BTN = "Cartas de versión",
	LETTERS_CLOSE = "Cerrar",
	LETTERS_COPY_LINK = "Copiar el enlace del sitio",
	LETTERS_CURRENT = "esta versión",
	LETTERS_INTRO = "Una carta por cada actualización, la más reciente primero.",
	LETTERS_ROW = "%s  -  %s",
	LETTERS_TITLE = "Cartas del desarrollador",
	LETTER_1_1_0 = "Versión 1.1.0, la versión Fernmelder. Es mucho. Haz clic por ahí. Nada explota.\n\n- El tablón de búsqueda de grupo.\n- La semana del Rey, con inscripciones.\n- Un tablón de artesanos y notas de botín.\n- Un interruptor de sonido para cada alerta.\n- Búsqueda en el censo y filas marcadas.\n- Una página de privacidad la primera vez que lo abres, para que elijas lo que compartes.\n- La lista de inactivos y los mentores.\n- Fuera de la red, términos bloqueados, vínculos de alters, la renovación de la clave y una línea fijada.\n- Los extras de la tesorería y las cuotas semanales.\n- Español, francés y alemán.",
	LETTER_1_1_0_TITLE = "La grande",
	LETTER_1_1_1 = "Versión 1.1.1. Querías leer el chat sin que se te escapara volando. Ahora puedes.\n\n- [Olympus], [Capitanes] y [Señores] viven ahora en la ventana de Olympus, en la pestaña Chat.\n- Busca en él, vuelve atrás, escribe desde la caja de abajo.\n- El engranaje guarda la configuración: silencia un canal, elige una ventana de chat o añade una pestaña Olympus al chat del juego.",
	LETTER_1_1_1_TITLE = "La pestaña Chat",
	LETTER_1_1_2 = "Versión 1.1.2. Menos preguntas en el chat. Ese es el sueño.\n\n- Haz clic derecho en un jugador para ver su versión de Olympus. ¿Va atrasado? Pídele que actualice. ¿No tiene el addon? Háblale de Olympus. Tú escribes el susurro, tú lo envías.\n- Cada página tiene un ? que dice lo que muestra y por qué dos jugadores pueden ver cifras distintas. Un único banco de respuestas, para que todos reciban la misma respuesta.\n- Informes de error cuando el autor pide uno.\n- Las pestañas de Chattynator funcionan.",
	LETTER_1_1_2_TITLE = "Clic derecho, pregunta, respuesta",
	LETTER_1_1_3 = "Versión 1.1.3.\n\n- Un clic normal ya no lanza una búsqueda /who a tus espaldas.\n- El censo y las búsquedas de jugadores se ejecutan desde sus propios botones, cuando tú lo pides.\n- El juego es quisquilloso con /who. Ahora nosotros también.\n\nEso es todo. Vuelve a lo que estabas haciendo.",
	LETTER_1_1_3_TITLE = "Nada de /who por sorpresa",
	LETTER_1_1_4 = "Versión 1.1.4. Actualización pequeña. No le busques segundas lecturas.\n\n- Los artesanos tienen su propia pestaña. Encuentra quién puede fabricar la cosa, susúrrale, listo.\n- Las pestañas laterales mantienen un mismo orden cuando se quedan sin espacio. Se acabó jugar al escondite con tus botones.",
	LETTER_1_1_4_TITLE = "Los artesanos tienen su propia pestaña",
	LETTER_1_1_5 = "Versión 1.1.5. Versión corta: menos cosas brillantes.\n\nBordes\n- Los antiguos bordes de rango ya no están: Señores oro, Capitanes plata, Asaltantes y Veteranos bronce.\n- Vienen otros nuevos, de la arena y más, y tendrás que ganártelos. Un borde que tiene todo el mundo no vale nada.\n- Por ahora se quedan tres: el Rey, alas de oro. El Alto Consejo, alas de plata. Los maestros de hermandad, alas de bronce.\n- También se muestran en los retratos de tu grupo, no solo en tu objetivo y tu foco.\n- Los maestros de hermandad pueden nombrar hasta 10 centuriones y un corresponsal por departamento desde la pestaña Hermandad: bronce sin alas. El Rey y el Alto Consejo nombran los 10 de la hermandad del Rey.\n- Todos los demás reciben la estrella en su placa de nombre. Siguen siendo Olympus, solo que sin medalla por conectarse.\n\nQuién es quién en el chat del juego\n- {star} un miembro de Olympus. Se muestra en Comercio, General, decir, grupo, banda y susurros. No en el chat de hermandad: tu hermandad ya sabe quién eres.\n- {gold} el Rey.\n- {silver} el Alto Consejo.\n- {bronze} los maestros de hermandad y las personas que nombran.\n- Los dragones también se muestran en el chat de hermandad. Las líneas de Olympus no llevan marca.\n\nMando\n- Con la interfaz de mando activada, Olympus se mantiene fuera de los menús de jugador de Blizzard, las ventanas de hermandad y la caja de chat. Los comandos /oly escritos necesitan ratón y teclado.\n- Los errores de las placas de nombre han desaparecido.\n- Cada versión pasa ahora una comprobación automática de mando antes de publicarse.\n\nAdemás\n- Todas las ventanas de Olympus llevan el mismo marco de bronce. Solo la ventana principal conserva el logo.\n- La pestaña Tesorería tiene su nuevo orden: saldo y banco primero, los primeros colaboradores plegados al final.\n- Artesanos: Cooking, Cocina y Culinaria son ahora una sola profesión.\n- Los decretos se abren con la agenda del ejército.\n- \"Invitar siempre\" cubre el grupo o la banda que lideras.\n- Las cuotas pagadas desde un alter confirmado cuentan para su principal.\n- Estas cartas. Una por actualización. ¿Te perdiste una? La \"i\" de la ventana de Olympus las guarda todas.",
	LETTER_1_1_5_TITLE = "Ahora los bordes significan algo",
	LETTER_1_2_0 = "Versión 1.2.0.\n\nEsta carta reúne lo que llegó con la 1.2.0 y las herramientas de Olympus que ya estaban disponibles antes. Si te perdiste esa actualización, empieza aquí.\n\nLas hermandades y sus cargos\n- {guild} Un maestro de hermandad fuera de la hermandad del Rey tiene un espacio de trabajo Hermandad: nombra hasta 10 centuriones y un corresponsal para cada uno de los seis departamentos, entre los propios miembros de la hermandad. Un título no es un ascenso en los rangos de hermandad de Blizzard.\n- {team} En la página de la lista de tu hermandad, los oficiales autorizados pueden asignar hasta 99 soldados a cada líder. Las demás hermandades usan sus centuriones nombrados; en la hermandad del Rey los líderes son consejeros del Alto Consejo firmados que pertenecen a esa hermandad. Cada grupo tiene su propio chat para sus miembros actuales.\n- {guild} Los corresponsales trabajan dentro de su propia hermandad. Guerra y Justicia tienen sus mesas existentes; Artesanía y Heráldica remiten a los tablones existentes, no a un nuevo flujo de trabajo departamental terminado. Un corresponsal de la Iglesia sigue necesitando un nombramiento de la Iglesia para acceder a ella.\n- {crown} Los roles del Alto Consejo vienen de la lista firmada, no de un título que alguien escribe. Los Senescales y las Manos del Rey conservan sus propias funciones. La flecha del minimapa apunta al Rey solo mientras él comparte su posición.\n\nLa Iglesia Misionera de Olympus\n- {church} Asmongold es la Cabeza. Los Doce Apóstoles dirigen redes misioneras, y cada hermandad de Olympus puede tener su propio corresponsal de la Iglesia.\n- {church} Los Apóstoles y los misioneros pueden nombrar misioneros bajo ellos: como máximo 10 nombrados directos por persona, cinco niveles por debajo de un Apóstol. El nombramiento y la retirada autorizados se quedan dentro de las funciones de esa persona.\n- {church} Personas lista a los miembros de la Iglesia. Lo mío, las cifras de reclutamiento y la sala de la Iglesia son para la Iglesia y su público autorizado. Una clasificación pública necesita el interruptor de quien la publica y tu propia elección de mostrar tu fila.\n- {church} Los informes del registro de hermandad ayudan a seguir el reclutamiento. Un informe queda pendiente hasta que se corrobora; un cambio reciente desde otra hermandad de Olympus no es un recluta nuevo. Son registros y puntos dentro del juego, no dinero ni un sistema de pagos.\n\nArtesanía y la tesorería\n- {craft} El tablón de Artesanos tiene encargos de objetos. Un artesano se ofrece a aceptar uno, el solicitante acepta, y sus condiciones y el chat del encargo quedan entre las partes en lugar de en el tablón público.\n- {craft} El comercio y el correo siguen siendo acciones tuyas. En un encargo directo, el solicitante confirma la entrega; un mensaje de addon no entrega un objeto ni oro por ti. Esta versión no activa la Cartera ni que el addon guarde oro para un encargo.\n- {guild} Las Tesorerías de hermandad reúnen los registros de banco que sus dueños aceptaron compartir, con una sola búsqueda. El acceso sigue el rol actual y la elección de compartir, no un título que alguien reclama.\n- {guild} Tu maestro de hermandad y su corresponsal de Tesorería nombrado pueden leer el registro del banco de su propia hermandad. El maestro de hermandad puede mostrárselo a los compañeros de hermandad. Esto no es un rol de custodio federal y no abre los bancos de otras hermandades.\n- {crown} Los custodios de la tesorería conservan su libro y sus funciones de peticiones de objetos. La entrega sigue siendo un correo o un comercio normal; una petición no es una compra automática.\n\nChats, la Guardia y noticias\n- {team} La pestaña Chat incluye salas de rol para maestros de hermandad, corresponsales de Tesorería, departamentos y centuriones, cuando tus funciones reales lo permiten. Previsualizar un rol no da acceso, y una sala no es cifrado.\n- {watch} La Guardia da a los oficiales autorizados de tu hermandad una mesa para denuncias, casos y Tabardos. La moderación del chat puede eliminar líneas y aplicar suspensiones temporales, con una auditoría guardada y una apelación al Alto Consejo.\n- {news} Vox Populi guarda tus últimas 30 preguntas, y un maestro de hermandad puede preguntar a su propia hermandad. Los resultados siguen el público de la pregunta y la elección de publicación.\n\nJuegos gratuitos e historial\n- {dice} La Tirada de Huesos se puede jugar por puntos con otro jugador en una taberna o un campamento. Usa /oly camp para plantar un campamento. La práctica con el tabernero te permite aprender las reglas sin otro jugador.\n- {dice} Los duelos y la Tirada de Huesos usan a los dos jugadores, sin árbitro. Los puntos de duelo tienen en cuenta el nivel de ambos luchadores; vencer a un rival de nivel mucho más bajo da poco o nada.\n- {dice} Buscar ofrece opciones de distancia para duelos y la Tirada de Huesos. La franja de cinco o diez niveles solo se aplica a los duelos; la Tirada de Huesos no tiene franja de nivel de rival.\n- {dice} Tu historial de juego guarda los resultados y los detalles de la mesa. La elección de compartir el historial de tu perfil sigue siendo tuya; guardar un registro local no es permiso para publicarlo.\n- {wanted} Se busca registra tus observaciones para revisión humana. Envía tus propias pruebas a un revisor autorizado; un registro local de una muerte por sí solo no otorga un puesto global de Cazador ni un marco.\n- {dice} Los juegos siguen siendo gratuitos: sin apuestas, sin oro en juego, sin boletos de Lotería de pago ni botes con cuota de entrada. El entrenamiento y la práctica no son una promesa de que los torneos ya se hayan validado.\n\nLos bordes, las marcas de chat y las protecciones de mando de actualizaciones anteriores se quedan. Abre la ayuda de la ventana de Olympus para volver a encontrar estas cartas.",
	LETTER_1_2_0_TITLE = "Las hermandades, la Iglesia y juegos para el ejército",
	LETTER_1_2_1 = "Versión 1.2.1.\n\nEsta actualización añade un chat a las mesas de Tirada de Huesos en directo, hace más fiables varias mesas de trabajo y te da una visión más clara de lo que este cliente sabe realmente. Los juegos siguen siendo gratuitos.\n\nLa Tirada de Huesos y tu chat\n- {dice} Una mesa multijugador real de Tirada de Huesos tiene un chat plegable a su derecha. Jugadores es solo para los dos jugadores; Todos incluye a los espectadores mientras esa mesa permita mirar. Un espectador no puede abrir la sala Jugadores.\n- {dice} El panel usa los bocadillos de chat, nombres y marcas habituales de Olympus. Cada mesa y cada pestaña guardan su propio borrador. Pliégalo cuando necesites espacio; volver a otra mesa no trae consigo el borrador de la mesa anterior.\n- {dice} Su entrada pertenece a la mesa, también en modo mando. No cambia el borrador de la pestaña Chat principal ni selecciona otro canal principal. La práctica con el tabernero y el historial de partidas antiguas no fingen tener un chat multijugador en directo.\n- {team} El engranaje del Chat puede ocultar en este cliente la etiqueta de hermandad junto a los nombres de los remitentes, incluido el panel de la Tirada de Huesos. Las hermandades siguen en las descripciones emergentes, la búsqueda y las pruebas de los mensajes. Los demás jugadores mantienen su propia elección de visualización.\n- {dice} Los permisos de la mesa se vuelven a comprobar a medida que la mesa cambia. Intentar enviar un mensaje no prueba que otro cliente lo recibiera; un envío bloqueado te avisa y no se reenvía automáticamente.\n- {dice} La resincronización y las comprobaciones de reconexión de la Tirada de Huesos protegen el juego presenciado localmente. La versión de la partida de un rival no puede sustituir tus decisiones presenciadas localmente. Varias correcciones de mensajes obsoletos o repetidos protegen también los encargos de fabricación y el historial de partidas y de perfil.\n\nLa Guardia y las apelaciones\n- {watch} Un aviso de suspensión temporal identifica a la moderación de Olympus, no el nombre del moderador. El personal autorizado sigue guardando quién hizo qué en su auditoría. Esto es privacidad de visualización, no anonimato en la red.\n- {watch} Las apelaciones sin resolver guardadas pueden volver a intentarse cuando los miembros del consejo se conecten más tarde. Un intento de envío fallido ya no marca para siempre una apelación como enviada.\n- {watch} Los inicios de sesión posteriores pueden recuperar las apelaciones guardadas y las suspensiones activas mediante intercambios limitados y comprobados. Un mensaje que nadie guardó no se puede reconstruir; una vista previa de rol nunca concede poderes de moderación.\n\nLas hermandades, la Iglesia y el registro real\n- {guild} El trabajo de departamento y el acceso al banco mantienen sus propios límites de hermandad. Un corresponsal necesita un nombramiento actual válido; un rango de hermandad que alguien reclama no le da esas funciones.\n- {church} Los nombramientos de la Iglesia y las comprobaciones de reclutamiento solicitadas ahora rechazan las respuestas que no pertenecen a la acción autorizada o a la comprobación que se envió. Esto mejora los registros; no convierte a dos personajes en prueba de dos personas distintas.\n- {crown} Cuando el Rey llama a alguien a una audiencia, puede dejar una breve nota escrita. El destinatario guarda la nota en su Crónica local con la autoría del Rey. La audiencia sigue siendo una cola, no un jurado, una votación ni un nuevo botón de castigo.\n- {guild} Una invitación del addon avisa a un oficial cuando el personaje está oculto de la red de Olympus, mostrando el motivo y la fecha guardados. El oficial sigue eligiendo. Las invitaciones nativas a la hermandad no se rechazan automáticamente, y el aviso es orientativo.\n\nSe busca y las clasificaciones revisadas\n- {wanted} Las pruebas deben pertenecer a una muerte infligida o sufrida observada por el propio remitente verificado. Una hermandad que se reclama o una identidad sin resolver no basta; un revisor autorizado sigue decidiendo a mano qué aceptar.\n- {wanted} Se corrigió un problema que impedía enviar las clasificaciones revisadas. Un revisor de confianza también puede retransmitir una clasificación firmada sin cambios a un cliente que ya confía de forma independiente en la clave de su emisor original.\n- {wanted} Una retransmisión no proporciona la primera clave de confianza de un nuevo destinatario, ni cambia la clave de un emisor, ni hace verdaderas unas pruebas sin revisar. Ponerse al día no garantiza que todos los clientes estén ya sincronizados.\n\nTus páginas semanales\n- {news} El Tablón tiene un resumen semanal público: el recuento conocido del ejército y su cobertura, el puesto de tu hermandad, la agenda de la semana, el último resultado público de Vox y el gasto que ya se permite hacer público.\n- {news} Solo compara reinicios guardados con una cobertura del censo comparable. El historial que falta sigue siendo desconocido, no cero. Los nombres de donantes privados, las contribuciones privadas y las encuestas restringidas no se convierten en estadísticas públicas.\n- {news} Tu semana, en cinco líneas es una página de pergamino personal en la pestaña El Reino de la ventana principal, disponible para todos los miembros. Está separada del resumen público del Tablón y del Trono real.\n- {news} El resumen personal solo informa de las pruebas de pago guardadas localmente. Sin un registro local de envío ni una recepción confirmada, lo dice; enviar una contribución por sí solo no prueba la recepción. Abrir cualquiera de las dos páginas no cambia ninguna elección de compartir.\n\nPequeños cambios, y lo que sigue desactivado\n- {team} La etiqueta corta del chat de raza es Skyborn.\n- {dice} Los nombres largos de animales de la Lotería se quedan encima de sus números, en una línea, con la animación habitual de cinco posiciones.\n- {dice} Las tiradas del tour de fotos ya no sustituyen la función global de tirada del juego. La práctica con el tabernero espera a que se cierre la conversación nativa antes de su traspaso al mando solo del addon.\n- {craft} Las invitaciones remotas a sesiones de prueba están desactivadas hasta que las permitas explícitamente. Desactiva esa opción para salir de una sesión; si la diriges tú, tu sesión se cierra.\n- {dice} No hay apuestas, oro en juego, boletos de Lotería de pago ni botes con cuota de entrada activados. Los módulos solo de apuestas quedan excluidos de los paquetes de prueba y de publicación.\n\nEstos cambios no significan que todas las propuestas a más largo plazo estén terminadas. Varias comprobaciones aún necesitan el cliente compatible real y varios jugadores conectados. Si algo sale mal, cuéntanos qué pasó, la mesa o la página, y la versión que usabas.",
	LETTER_1_2_1_TITLE = "Un chat junto a la Tirada de Huesos, y registros más claros",
	LETTER_1_2_2 = "Versión 1.2.2.\n\nAntes de nada, perdón por los errores de las últimas versiones, y por tardar tanto en arreglarlos. De miércoles a domingo he estado atrapado en otro proyecto, una cosa corporativa B2B (mi Ragnaros personal). Gracias, de verdad, por tu paciencia y tu comprensión: con la cantidad de problemas que tuvieron las últimas actualizaciones, has sido increíblemente amable.\n\nNinguno de ellos puso en riesgo tu cuenta ni tu oro.\n\nLo que arregla esta actualización\n- {news} Los tirones: las comprobaciones de la carrera de niveles se ejecutaban con cada mensaje del censo y podían congelar el juego un momento en horas de mucha actividad. Ahora son ligeras y están repartidas, el mapa del mundo ya no se redibuja mientras está cerrado, y las tareas de cada minuto ya no caen en el mismo fotograma. Si vuelve a pasar, /oly perf mide Olympus y muestra un informe que puedes copiar y enviarme.\n- {news} La página de privacidad ya no se vuelve a abrir sola en cada sesión.\n- {crown} La carta del Rey sobre un marco nuevo se muestra una vez, en una ventana propia, y nunca al Rey sobre sí mismo.\n- {dice} Tirada de Huesos: no hay ventana del tabernero en cada visita a una posada (solo cuando la pides); si varios jugadores te invitan, Olympus pregunta una vez si quieres detener las invitaciones (vuelve a activarlas en la página de privacidad); elegir y devolver un dado ya no bloquea la tirada.\n- {guild} Expulsar a alguien de la hermandad o cambiar un rango ya no falla por culpa de Olympus.\n- {church} Los recuentos de la Iglesia ya no bajan cuando se llena el registro de un custodio, y las confirmaciones de un Apóstol ocupado ya no se pierden.\n- {guild} El maestro de otra hermandad que está conectado ya no aparece como ausente por culpa de un informe antiguo.\n- {team} Hacer clic en [Olympus], [Capitanes] o [Señores] en el chat abre la caja para escribir ahí, como [Grupo]. Las salas de raza muestran las razas de tu facción, con una sala Skyborn.\n- {news} El atajo de Olympus es ahora Mayús + tu tecla de hermandad (el juego se quedó con la Y), y puedes elegir tu propia tecla en la Asignación de teclas del juego.\n- {watch} Solo el autor, el Rey y el Alto Consejo pueden pedirte que actualices.\n- {news} Muchas correcciones de seguridad y fiabilidad de dos revisiones independientes: saltos de capa, listas firmadas, los testigos de la Iglesia, la mesa de fabricación, las copias de seguridad y más.\n\nY más, para quien se perdió la 1.2.1: un chat junto a las mesas de Tirada de Huesos en directo, varias mesas de trabajo más fiables y una visión más clara de lo que este cliente sabe realmente. Los juegos siguen siendo gratuitos.\n\nLa Tirada de Huesos y tu chat\n- {dice} Una mesa multijugador real de Tirada de Huesos tiene un chat plegable a su derecha. Jugadores es solo para los dos jugadores; Todos incluye a los espectadores mientras esa mesa permita mirar. Un espectador no puede abrir la sala Jugadores.\n- {dice} El panel usa los bocadillos de chat, nombres y marcas habituales de Olympus. Cada mesa y cada pestaña guardan su propio borrador. Pliégalo cuando necesites espacio; volver a otra mesa no trae consigo el borrador de la mesa anterior.\n- {dice} Su entrada pertenece a la mesa, también en modo mando. No cambia el borrador de la pestaña Chat principal ni selecciona otro canal principal. La práctica con el tabernero y el historial de partidas antiguas no fingen tener un chat multijugador en directo.\n- {team} El engranaje del Chat puede ocultar en este cliente la etiqueta de hermandad junto a los nombres de los remitentes, incluido el panel de la Tirada de Huesos. Las hermandades siguen en las descripciones emergentes, la búsqueda y las pruebas de los mensajes. Los demás jugadores mantienen su propia elección de visualización.\n- {dice} Los permisos de la mesa se vuelven a comprobar a medida que la mesa cambia. Intentar enviar un mensaje no prueba que otro cliente lo recibiera; un envío bloqueado te avisa y no se reenvía automáticamente.\n- {dice} La resincronización y las comprobaciones de reconexión de la Tirada de Huesos protegen el juego presenciado localmente. La versión de la partida de un rival no puede sustituir tus decisiones presenciadas localmente. Varias correcciones de mensajes obsoletos o repetidos protegen también los encargos de fabricación y el historial de partidas y de perfil.\n\nLa Guardia y las apelaciones\n- {watch} Un aviso de suspensión temporal identifica a la moderación de Olympus, no el nombre del moderador. El personal autorizado sigue guardando quién hizo qué en su auditoría. Esto es privacidad de visualización, no anonimato en la red.\n- {watch} Las apelaciones sin resolver guardadas pueden volver a intentarse cuando los miembros del consejo se conecten más tarde. Un intento de envío fallido ya no marca para siempre una apelación como enviada.\n- {watch} Los inicios de sesión posteriores pueden recuperar las apelaciones guardadas y las suspensiones activas mediante intercambios limitados y comprobados. Un mensaje que nadie guardó no se puede reconstruir; una vista previa de rol nunca concede poderes de moderación.\n- {watch} Tu denuncia ahora también llega al Rey y al Alto Consejo, en su Guardia (Denuncias y Casos), a través del cliente del Rey mientras está activo, una vez que ya te conoce en tu hermandad (por tus líneas en los chats de Olympus, por ejemplo); solo guarda las líneas que oyó él mismo. Con él desactivado, la denuncia espera un día en tu cliente. Los oficiales de tu hermandad la siguen recibiendo como antes.\n\nLas hermandades, la Iglesia y el registro real\n- {guild} El trabajo de departamento y el acceso al banco mantienen sus propios límites de hermandad. Un corresponsal necesita un nombramiento actual válido; un rango de hermandad que alguien reclama no le da esas funciones.\n- {church} Los nombramientos de la Iglesia y las comprobaciones de reclutamiento solicitadas ahora rechazan las respuestas que no pertenecen a la acción autorizada o a la comprobación que se envió. Esto mejora los registros; no convierte a dos personajes en prueba de dos personas distintas.\n- {crown} Cuando el Rey llama a alguien a una audiencia, puede dejar una breve nota escrita. El destinatario guarda la nota en su Crónica local con la autoría del Rey. La audiencia sigue siendo una cola, no un jurado, una votación ni un nuevo botón de castigo.\n- {guild} Una invitación del addon avisa a un oficial cuando el personaje está oculto de la red de Olympus, mostrando el motivo y la fecha guardados. El oficial sigue eligiendo. Las invitaciones nativas a la hermandad no se rechazan automáticamente, y el aviso es orientativo.\n- {guild} Con ratón y teclado, mientras una de las ventanas de hermandad del juego está abierta, Olympus hace sus preguntas en sus propias ventanas, y ya no añade sus líneas al menú de clic derecho de la lista de hermandad del juego, donde están el ascenso, el descenso, el rango y la expulsión propios del juego. Esas acciones se rechazaban de vez en cuando con una pregunta de Olympus abierta.\n\nSe busca y las clasificaciones revisadas\n- {wanted} Las pruebas deben pertenecer a una muerte infligida o sufrida observada por el propio remitente verificado. Una hermandad que se reclama o una identidad sin resolver no basta; un revisor autorizado sigue decidiendo a mano qué aceptar.\n- {wanted} Se corrigió un problema que impedía enviar las clasificaciones revisadas. Un revisor de confianza también puede retransmitir una clasificación firmada sin cambios a un cliente que ya confía de forma independiente en la clave de su emisor original.\n- {wanted} Una retransmisión no proporciona la primera clave de confianza de un nuevo destinatario, ni cambia la clave de un emisor, ni hace verdaderas unas pruebas sin revisar. Ponerse al día no garantiza que todos los clientes estén ya sincronizados.\n\nTus páginas semanales\n- {news} El Tablón tiene un resumen semanal público: el recuento conocido del ejército y su cobertura, el puesto de tu hermandad, la agenda de la semana, el último resultado público de Vox y el gasto que ya se permite hacer público.\n- {news} Solo compara reinicios guardados con una cobertura del censo comparable. El historial que falta sigue siendo desconocido, no cero. Los nombres de donantes privados, las contribuciones privadas y las encuestas restringidas no se convierten en estadísticas públicas.\n- {news} Tu semana, en cinco líneas es una página de pergamino personal en la pestaña El Reino de la ventana principal, disponible para todos los miembros. Está separada del resumen público del Tablón y del Trono real.\n- {news} El resumen personal solo informa de las pruebas de pago guardadas localmente. Sin un registro local de envío ni una recepción confirmada, lo dice; enviar una contribución por sí solo no prueba la recepción. Abrir cualquiera de las dos páginas no cambia ninguna elección de compartir.\n\nPequeños cambios, y lo que sigue desactivado\n- {team} La etiqueta corta del chat de raza es Skyborn.\n- {team} El atajo de Olympus es ahora Mayús + tu tecla de hermandad (Mayús+J por defecto), que solo se usa mientras esa tecla no tenga otra asignación. También puedes elegir tu propia tecla en la Asignación de teclas del juego, en la sección de addons, bajo Olympus.\n- {crown} Pedir que actualice, en el menú de clic derecho de un jugador, es ahora solo para el Rey, el Alto Consejo y el autor del addon. Tu addon ignora la petición de cualquier otro, que las versiones antiguas aún pueden enviar. Comprobar versión sigue disponible para todos los miembros.\n- {dice} Los nombres largos de animales de la Lotería se quedan encima de sus números, en una línea, con la animación habitual de cinco posiciones.\n- {dice} Las tiradas del tour de fotos ya no sustituyen la función global de tirada del juego. La práctica con el tabernero espera a que se cierre la conversación nativa antes de su traspaso al mando solo del addon.\n- {craft} Las invitaciones remotas a sesiones de prueba están desactivadas hasta que las permitas explícitamente. Desactiva esa opción para salir de una sesión; si la diriges tú, tu sesión se cierra.\n- {dice} No hay apuestas, oro en juego, boletos de Lotería de pago ni botes con cuota de entrada activados. Los módulos solo de apuestas quedan excluidos de los paquetes de prueba y de publicación.\n\nEstos cambios no significan que todas las propuestas a más largo plazo estén terminadas. Varias comprobaciones aún necesitan el cliente compatible real y varios jugadores conectados. Si algo sale mal, cuéntanos qué pasó, la mesa o la página, y la versión que usabas.",
	LETTER_1_2_2_TITLE = "Correcciones, y gracias por tu paciencia",
	LETTER_1_2_3 = "Versión 1.2.3.\n\nUna rápida, con lo que vimos en la transmisión del Rey y lo que nos contaron.\n\nQué corrige esta actualización\n- {news} Memoria: con la ventana de Olympus abierta, la pestaña Chat rehacía todas las líneas con cada mensaje nuevo, unos 2,5 MB de memoria cada vez. Ahora dibuja solo lo que cambió. La Iglesia, la lista de la hermandad y el censo también trabajan mucho menos cada minuto.\n- {news} /oly perf ahora también mide la memoria: lo que asigna cada parte de Olympus y los mayores saltos.\n- {news} La página de privacidad ya no vuelve a abrirse después de la actualización si ya la habías cerrado.\n- {news} La ventana de Olympus ya no se abre sola cuando otro miembro acepta tu pedido de fabricación.\n- {news} La carta de actualización aparece unos segundos después de iniciar sesión, no un minuto más tarde (justo después de la página de privacidad, si tiene una pregunta para ti).\n- {crown} La corona del Rey en el mapa funciona justo después de iniciar sesión, sin tener que desactivarla y volver a activarla.\n- {crown} Los decretos reales y las inspecciones de tabardo solo llegan a todo el ejército si vienen de la Corona y del Alto Consejo, y lo mismo pasa con las Llamadas a las armas y las Reuniones (también las de las Manos del Rey). Las de un maestro de hermandad ahora llegan solo a su propia hermandad, igual que las de sus oficiales y las demás acciones que antes llegaban a todas las hermandades.\n- {wanted} Los más buscados por fin funciona: un jugador de la Horda que mata a uno de los nuestros, o al que mata uno de los nuestros, entra solo en la lista, y todos los miembros lo ven. Cada muerte suma a su recompensa según el cargo y el nivel de a quien mató; una baja paga su nivel y toda su recompensa, que luego vuelve a empezar de cero; matar a quien te mató suma 100 por venganza. Solo fuera de instancias. /oly wanted status muestra lo que se capturó y por qué algo no se capturó.\n- {church} Los 3 mejores misioneros llevan el Cayado del Pastor, en oro, plata y bronce, con su título.\n- {news} Un marco que ganas ya no oculta la cornucopia: tu perfil muestra solo los marcos que puedes llevar, y tu elección se mantiene.\n- {team} Las salas de chat de raza y de clase desaparecen de la pestaña Chat: nadie las usaba.\n- {dice} Los juegos siguen siendo gratis: sin apuestas, sin oro en juego.\n\nGracias por cada informe. Que sigan llegando.",
	LETTER_1_2_3_TITLE = "Correcciones de la transmisión del Rey y un Olympus más ligero",
	LETTER_1_2_4 = "Versión 1.2.4.\n\nEsta versión reúne las correcciones de hermandad, Iglesia, chat y registros. Los juegos siguen siendo gratis: sin apuestas, sin importes de entrada ni movimientos automáticos de oro.\n\nChat y juegos\n- {team} Las salas por cargo siguen el consejo firmado real y los nombramientos actuales de la hermandad. Hay salas separadas para maestros de hermandad, Legados, departamentos, Apóstoles, misioneros y La Guardia. Una vista previa nunca da acceso; el acceso del autor no incluye la sala privada del Alto Consejo.\n- {team} Tu lista de cargos se divide en páginas en lugar de cortarse tras doce salas. Los mensajes que esperan en la cola de envío siguen visibles. Una línea rechazada o entregada solo en parte explica lo que pasó en vez de desaparecer; no se reenvía en silencio a quienes ya la recibieron.\n- {team} Los paquetes del censo en segundo plano ya no rehacen la ventana principal del chat cada pocos segundos. Los mensajes directos y los cambios de moderación conservan sus propias actualizaciones inmediatas.\n- {dice} El selector de Juegos identifica las salas de Arena y de Huesos. Una conversación multijugador de Huesos puede seguir con sus jugadores después de la partida; los antiguos espectadores conservan solo el historial que recibieron, sin permiso para enviar mensajes cuando termina. La práctica con el tabernero no tiene sala multijugador.\n\nRegistros que sobreviven a una noche tranquila\n- {dice} Las partidas gratis de Huesos y los duelos directos conservan sus mitades firmadas originales del resultado. Los miembros comunes que las guardaron pueden reenviar los registros que faltan a los miembros que inicien sesión más tarde. Un reenvío no prueba la identidad de otro jugador: las claves desconocidas esperan al jugador original, y los registros repetidos no cuentan dos veces.\n- {dice} Los resultados en conflicto se ponen en cuarentena solo después de verificar las firmas originales. Una acusación sin firma no puede borrar un resultado válido. Los resúmenes mensuales se pueden sellar tras revisarlos; un sello sin sus totales correspondientes nunca permite borrar los registros originales.\n- {guild} Los nombramientos aceptados de la hermandad, las Manos del Rey y las instantáneas de Tesorería afiliadas siguen disponibles mientras su fuente está desconectada. Una prueba de que el nombramiento terminó sigue revocándolo; estar desconectado, por sí solo, no.\n\nHermandades y la Iglesia\n- {guild} Las listas del Censo y del Reino muestran el nivel medio y lo usan de forma coherente al ordenar hermandades empatadas. Los encabezados y los detalles de cada fila caben en el diseño actual.\n- {church} Un Apóstol o misionero puede nombrar a doce misioneros directos, dentro del límite total de cinco mil de la Iglesia. Los libros de nombramientos grandes se ponen al día por partes limitadas en lugar de enviar una y otra vez solo su primera página.\n- {church} Una sincronización incompleta no debe convertir a un Apóstol en misionero ni expulsar nombramientos aceptados solo porque entradas inválidas llenaron una cola.\n- {church} El corresponsal de la Iglesia de una hermandad gana los días observados completos por encima de 950 miembros durante su propio nombramiento. Una nueva gestión empieza de cero, no con la racha de la persona anterior. Los días desconocidos pausan la racha sin dar puntos ni borrar días probados; un día observado con 950 miembros o menos rompe la racha. La media diaria de miembros desempata. No se pueden inventar pruebas antiguas que ningún guardián superpuesto conservó.\n- {crown} Los Centuriones ahora son Legados: hasta veinticinco líderes nombrados explícitamente por hermandad, cada uno organizándose a sí mismo y a hasta treinta y nueve compañeros de hermandad, cuarenta en total. La hermandad del Rey también nombra a sus Legados a mano; pertenecer al Alto Consejo, por sí solo, no nombra a nadie. Esto sustituye las antiguas reglas de centurias.\n- {team} Un Legado puede gestionar la composición acordada de su propio grupo y coordinar la asistencia a eventos, bandas y guerras. La nominación explica ese propósito. Los grupos que ya superan el tamaño se conservan para una revisión deliberada, no se recortan en silencio; no ocurre ninguna invitación, expulsión ni ascenso automático en la hermandad. Los grupos son opcionales y flexibles: puedes jugar con otro líder cuando el tuyo está desconectado. Los recuentos de conectados con la lista reciente muestran quién está disponible y qué se desconoce.\n- {guild} Departamento de Heráldica es el nombre que se muestra; los antiguos nombres firmados de Patrimonio siguen siendo compatibles. La Agenda de la hermandad, los decretos y las reuniones mantienen sus propios límites de hermandad y las funciones verificadas del maestro de hermandad y del corresponsal de Heráldica. Las acciones globales conservan sus permisos de la Corona verificados por separado.\n- {guild} Las sugerencias de nominación de corresponsales explican las funciones del departamento, no solo dónde hacer clic.\n\nTesorería y un propósito voluntario\n- {gold} Tu propio estado de pago ahora distingue entre un envío nativo que espera al libro, un recibo confirmado y la información desconocida. Solo el oro realmente recibido puede confirmar un pago; una entrada manual en el libro no puede fabricar un recibo. Tu recibo privado se puede recuperar de su guardián cuando más adelante estén conectados a la vez.\n- {gold} El recordatorio local tiene su propio interruptor de Privacidad por personaje. Se queda en silencio en combate y en instancias, y nunca rellena ni envía correo o comercio solo porque se abrió una ventana.\n- {gold} El Rey puede abrir una campaña voluntaria de catorce días de oro o materiales. Un guardián asigna explícitamente un recibo confirmado una sola vez; el mínimo semanal, las ventas, las transferencias y las ediciones manuales del libro no cuentan. Al ejército solo le llega el progreso agregado. Cerrar el propósito guarda la nota de compra del Rey en la Crónica; no se añade ningún bote, depósito en garantía ni movimiento automático de oro.\n- {guild} Cuando el mismo personaje cambia de hermandad, tanto ese jugador como el maestro de la hermandad de destino pueden consentir una pequeña copia privada del historial conservado. Las citas más antiguas siguen sin verificar. Las firmas originales recopiladas también pueden viajar como un archivo privado y consentido, con las fechas originales y una clave original verificada por separado. Las claves que faltan siguen desconocidas. El Botín privado va directamente entre maestros de hermandad que dan su consentimiento, nunca a través del miembro. Ninguna de las dos vías importa pagos, perdones, cargos ni claves.\n- {guild} Los guardianes actuales atribuyen explícitamente por hermandad los recibos nativos en cobre y los gastos reales de los eventos. Tu maestro de hermandad verificado solo ve los agregados de tu propia hermandad; las fuentes que faltan siguen desconocidas. Ninguna acción de banco, correo o comercio es automática.\n- {news} Las semanas registradas privadas conservan la primera semana cubierta sin un recibo nativo suficiente. La segunda puede avisar en privado al jugador y luego a su maestro de hermandad verificado actual. Se admiten los puntos de control nativos de reinicio de la propia hermandad. El maestro nativo firmado real de una hermandad hermana puede aceptar, durante 31 días, enviar puntos de control de reinicio firmados y completos solo al Tesorero federal. Se requieren observaciones completas de los límites, grupos de alts confirmados y la cantidad capturada en el reinicio real. Las pruebas que faltan, la retirada, un cambio de liderazgo o las claves desconocidas siguen siendo desconocidos; un censo nunca prueba un pago no realizado. Los libros también necesitan un seguimiento original y completo de los recibos nativos iniciado antes de la semana: una fecha de apertura antigua o un libro de cuentas genérico restaurado o remoto no puede probar una ausencia. Los recibos positivos siguen siendo cotas inferiores. Ninguna función se bloquea y ninguna acción nativa ni pago es automático.\n- {guild} Una fusión de hermandades con nombre puede archivar un índice congelado de registros solo después de que el Rey real y los dos maestros de hermandad actuales firmen el mismo mandato antes de que la hermandad de origen se disuelva. Cada personaje da su consentimiento por separado. El Botín privado va solo entre guardianes hacia el maestro heredero exacto que lo aprueba. Las firmas originales, las fechas y las etiquetas explícitas de testigo actual siguen visibles; un archivo parcial consentido puede reanudarse tras recargar. Ningún alt, maestro de hermandad sucesor ni registro de moderador hereda el permiso, y no se importa ningún rango, clave, pago ni perdón activo.\n\nPerfiles, honores y Se busca\n- {news} Ver perfil abre el perfil normal de Olympus, también cuando haces clic derecho sobre ti mismo. Ya no te lleva a un perfil solo de Arena.\n- {news} Los honores pequeños de cruz son más grandes. El retrato de cargo de bronce liso ahora es solo para corresponsales, no para Legados; su identidad actual en el chat y en la placa de nombre se mantiene. Una insignia propia de Legado aún espera el arte elegido. Las elecciones de marcos ganados y la distinción entre una apariencia personalizada local y lo que ven otros jugadores siguen intactas.\n- {wanted} Las muertes repetidas dentro del intervalo de protección siguen siendo pruebas, pero no suman recompensa ni otra baja contada. Las entradas vacías con cero puntos y cero bajas contadas quedan fuera de la lista y de los marcadores en el mapa. Los puntos de recompensa son la recompensa aún no cobrada; el número de bajas no es la misma cantidad.\n- {wanted} Los informes de miembros comunes verificados de Olympus pueden llegar a otras hermandades. Los alts vinculados confirmados comparten los tiempos de espera de recompensa; las cuentas no vinculadas no se pueden identificar como la misma persona. Los informes del cliente siguen sin ser una prueba certificada por el servidor; la captura multijugador y los controles contra el farmeo necesitan jugadores reales.\n\n- {wanted} Las listas de Se busca y de Cazadores empiezan con sus cinco primeras entradas. Cada lista se amplía por separado de diez en diez, y las entradas con cero puntos y cero bajas contadas siguen ocultas.\n- {wanted} La última zona vista de un objetivo de Se busca solo se guarda cuando este cliente conserva su propia prueba aceptada de baja o de muerte. Las filas reenviadas no llevan zona; una marca nativa más reciente en el mapa puede sustituir el avistamiento guardado. El addon no guarda coordenadas exactas, y el avistamiento es una prueba del cliente, no certificada por el servidor.\n- {wanted} La puntuación de Cazador ahora suma un punto base por cada diez niveles del objetivo de la Horda, redondeando hacia arriba, toda la recompensa actual del objetivo y 100 puntos por una venganza válida. La migración solo vuelve a procesar el historial demostrable; los totales antiguos sin resolver se archivan en lugar de adivinarse. Un jugador cuya puntuación baja recibe una explicación personal, una sola vez.\n- {news} Se busca/Cazadores, donantes, Tesorería de la hermandad, servicio y ocupación de la Iglesia, Arena, Huesos y las clasificaciones del reino por nivel y por raza ahora tienen páginas de Reglas legibles dentro de la ventana principal. La orden privada de cobro de tarifas de fabricación también tiene una, pero no es una clasificación de honor. Las restricciones de acceso existentes siguen decidiendo quién puede ver cada página.\n\nLotería y límites seguros\n- {dice} Solo el Rey, el Alto Consejo firmado y el autor pueden usar los controles de Lotería del personal. La Lotería no es una clasificación pública. La práctica individual gratis sigue disponible; los boletos con oro y las apuestas siguen excluidos de los paquetes.\n- {watch} La rendición de cuentas del personal sigue siendo privada para el personal autorizado. Una vista previa de cargo, una reclamación de rango de hermandad o un paquete reenviado no pueden dar acceso a la moderación ni a la tesorería.\n- {watch} La Guardia ahora tiene solicitudes privadas de Justicia: asignaciones explícitas del Rey o del Alto Consejo real, un acuse de recibo y el tiempo transcurrido hasta un intento manual de expulsión. La ausencia posterior en la lista es una observación aparte; solo la revisión explícita del emisor original registra la finalización confirmada por una persona. Una API automática o una salida, por sí solas, nunca cuentan como finalización. Los informes se cuentan por separado como pares aceptados conservados localmente con cobertura parcial, no como totales históricos ni como calidad. Las pruebas originales del emisor y del asignado ahora se pueden recuperar en privado a través del personal autorizado, también mientras los actores originales están desconectados. La lista de respuestas compara medianas del recibo al intento manual con el tamaño de la muestra y la cobertura desconocida; los informes y las finalizaciones confirmadas por una persona siguen separados. Esto no es una puntuación de calidad ni un honor nuevo.\n\nPara esta versión de prueba\n- {news} Prueba la entrega en salas con otra hermandad, una conversación de Huesos después de la partida y una recarga, la captura de Se busca y un inicio de sesión tardío que reciba registros de partidas firmados. Las pruebas sin conexión no pueden establecer esos resultados en vivo.\n- {news} Las reglas de puntuación de departamentos que aún necesitan decisiones no se anuncian como clasificaciones terminadas. No se ha activado ninguna tarifa en oro ni función de apuestas para llenar un hueco.\n\nGracias por cada informe.",
	LETTER_1_2_4_TITLE = "Hermandades, la Iglesia y registros que perduran",
	LETTER_1_2_5 = "Versión 1.2.5.\n\nRespuestas en el chat\n- {team} Haz clic derecho en una línea guardada del Chat de Olympus y elige Responder. Aparece una referencia compacta sobre el cuadro de mensaje, la línea enviada conserva la referencia citada y la X la cancela antes de enviar.\n- {team} La referencia guarda solo la sala, el remitente y el texto conservado que ese cliente ya ve. No da acceso a la sala, poder de moderación ni la identidad de otro jugador. Los clientes más antiguos reciben un prefijo de texto legible.\n\nLegados, corresponsales y honores\n- {crown} Los Legados ahora usan el escudo de Legado elegido. Los corresponsales usan el escudo de su departamento. El antiguo marco de cargo de bronce sin alas ya no lo usa ninguno de los dos cargos; un maestro de hermandad sigue conservando el marco de bronce con alas.\n- {crown} Un consejero firmado del Alto Consejo puede mostrar el escudo de su departamento firmado sin sustituir el marco plateado del Consejo. Un honor ganado también se mantiene debajo de su escudo de cargo independiente.\n- {guild} Los Legados y corresponsales existentes y recién nombrados reciben una explicación personal del cambio, de la decisión del Alto Consejo y de las funciones de su cargo. Volver a conectarse no la repite; un cambio real de nombramiento más adelante puede explicar el nuevo cargo una vez.\n- {news} Las familias de honores simples usan tamaños visibles normalizados y centrado. Esto cambia su presentación, no su dueño, su puntuación ni su verificación.\n- {news} El autor puede inspeccionar localmente cualquier escudo de cargo con /oly borders test role-legate o role-<department-key>, y terminar con /oly borders test off. La vista previa mantiene el marco real debajo y no envía nada.\n\nSe busca y registros compartidos\n- {wanted} Se busca, Cazadores del mes y Cazadores de siempre abren cada uno con cinco filas y se amplían por separado de diez en diez. Salir de Los más buscados vuelve a reducir las tres a cinco; abrir Reglas y volver mantiene la página que estabas leyendo.\n- {wanted} Una baja o muerte entre hermandades conservada localmente permanece en el libro perenne aunque aún no se pueda probar la pertenencia a la hermandad. Solo las filas con pruebas independientes de pertenencia pueden afectar al tablero compartido y firmado de Cazadores. Las pruebas posteriores respaldadas por la lista de la hermandad ascienden la misma fila en lugar de contarla dos veces.\n- {wanted} La identidad del personaje, las pruebas de pertenencia a la hermandad y las pruebas de cargo se comprueban por separado. La puntuación de cargo compartida es determinista entre clientes; una observación de cargo solo local no puede cambiar en silencio la puntuación pública.\n- {guild} Las colas de registros de partidas conservados tienen un límite justo por remitente, así que un solo par no puede expulsar los registros de todos los demás remitentes. Los desconocidos no verificados del canal público no pueden crear demanda de saltos de capa ni controlar su tiempo de espera.\n\nPor favor, prueba\n- {news} Prueba Responder con un segundo cliente actualizado, cada escudo de cargo en jugador/objetivo/foco, salir y volver a abrir Los más buscados después de ampliar sus listas, y un inicio de sesión tardío que reciba registros conservados. Las pruebas sin conexión cubren las reglas, pero solo los clientes en vivo pueden confirmar la interacción final y la ruta de reenvío.",
	LETTER_1_2_5_1 = "Versión 1.2.5.1.\n\n- {guild} Un oficial de la hermandad puede usar /oly key off para quitar una clave de reino solo de hermandad que no coincide y devolver la hermandad al canal público de Olympus.\n- {team} La instrucción de recuperación viaja solo dentro del canal de hermandad de Blizzard, y solo un oficial actual puede emitirla. Los compañeros de hermandad actualizados se mueven juntos y recuerdan la clave privada retirada, para que un mensaje antiguo y retrasado no pueda volver a separarlos.\n- {news} Esto vuelve a conectar el censo compartido y el chat de Olympus de una hermandad separada por accidente por su clave. No inventa informes históricos que faltan; los informes en vivo se vuelven a llenar cuando la hermandad se reincorpora.",
	LETTER_1_2_5_1_TITLE = "Reconecta una hermandad separada",
	LETTER_1_2_5_TITLE = "Respuestas, escudos de cargo y registros más estables",
	LETTER_1_3_0 = "Versión 1.3.0.\n\n- {news} Las clasificaciones y los registros públicos ahora conservan su fuente verificada y los titulares de libros que cumplan los requisitos pueden repetirlos, así que los clientes que llegan tarde o vuelven pueden recuperar el mismo estado duradero después de que el testigo original se desconecte.\n- {church} Los registros de servicio de la Iglesia conservan el historial de reclutamiento confirmado entre sesiones. El tiempo desconocido se pausa en lugar de convertirse en un falso cero, y un nuevo corresponsal empieza un nuevo mandato personal.\n- {wanted} Los más buscados y Cazadores abren con cinco filas cada uno, se amplían por separado, conservan el historial probado con la puntuación reequilibrada y muestran el último avistamiento con fecha sin fingir que un avistamiento antiguo está en vivo.\n- {guild} Los Legados organizan grupos de hasta cuarenta, con hasta veinticinco por hermandad. Su presentación de cargo, sus insignias y sus avisos siguen la estructura actual del Alto Consejo.\n- {craft} La fabricación, la Tesorería, la Arena y los juegos exponen solo sus resúmenes públicos permitidos. Sus libros duraderos rechazan las afirmaciones mal formadas o imposibles de verificar en lugar de dejar que un remitente invente una puntuación.\n- {watch} Los informes, las sanciones y los registros de Justicia mantienen su público. El personal puede ver al miembro del personal responsable; el jugador afectado solo ve el cargo de Olympus responsable, lo que protege a cada moderador de ser señalado.\n- {team} Las respuestas del chat, las salas de partida, las opciones de privacidad y las exportaciones de Companion usan los mismos registros acotados que acepta el propio addon. No se exporta nada antes de aceptar el Acuerdo de Olympus.\n- {dice} Huesos y la Arena recibieron en esta versión la interfaz integrada y las correcciones de registros. La práctica sigue separada de las clasificaciones públicas de jugadores.\n- {crown} Las marcas de ubicación usan avistamientos recientes y sujetos a permiso, desaparecen cuando caducan o se retira el permiso, y nunca recogen ni dibujan posiciones exactas dentro de instancias.\n\nEsta es una versión grande y por eso abre la línea 1.3. Las pruebas sin conexión cubren las reglas y los límites de los datos; el reenvío multijugador, la interfaz de cada cliente y la colocación en el mapa todavía dependen de la observación en vivo dentro del juego.",
	LETTER_1_3_0_TITLE = "Un Olympus compartido",
	LETTER_1_3_2 = "Versión 1.3.2.\n\n- {news} Estadísticas del censo ahora indica que las personas son una estimación y muestra su fórmula: personajes contados menos los alts vinculados confirmados que conoce este cliente. Actualizar por sí solo no vincula alts, así que las confirmaciones que faltan pueden mantener alta la estimación.\n- {craft} Las filas aceptadas de la clasificación de la Tesorería se mantienen por delante de las propuestas más nuevas sin confirmar.\n- {team} Se corrigieron dos regresiones de interfaz y de clasificación que dependían del orden de la batería completa de pruebas y que encontró la CI.\n- {team} El Companion Bridge opcional ahora exporta la identidad con nombre y el chat de Olympus aceptado solo después de aceptar su aviso aparte. Tu propio BattleTag se incluye solo con ambos Acuerdos, para mostrarlo al personal y vincular cuentas, nunca como autoridad de pertenencia ni de testigo.\n",
	LETTER_1_3_2_TITLE = "Recuentos compartidos, aclarados",
	LETTER_1_3_3 = "Versión 1.3.3.\n\n- {news} Una nueva carpeta opcional, Olympus - Site Aggregate, viene en la misma descarga. En una hermandad de la Alianza llamada Olympus u Olympus I a X, escribe /oly site export y luego /reload, y el juego escribe un recuento enmascarado de tu propia hermandad (miembros y conectados, nada más) en su propio archivo para el sitio web de Olympus. No se sube nada: eliges ese archivo en el sitio web y das tu consentimiento allí.\n- {team} Elige el archivo mientras el juego sigue abierto: tu próximo cierre de sesión o /reload lo vacía, así que una exportación antigua nunca se queda ahí. Cambiar de hermandad retira una exportación pendiente, y /oly site clear la elimina.\n- {team} /oly site sigue las mismas reglas de seguridad con mando de juego que los demás comandos.\n",
	LETTER_1_3_3_TITLE = "Tu hermandad en el sitio web",
	LETTER_1_4_0 = "Su Majestad. Soldados de Olympus. Señores, Capitanes, Consejeros, y ese que todavía no se puso el tabardo.\n\nOíd: hoy se abre el verdadero reino.\n\nEn la beta hicieron lo imposible. Más de cien mil personajes en el censo, contando JcE, y casi cien mil descargas de este humilde artilugio. Los escribas contaron dos veces y pidieron un aumento.\n\nPero la beta ya es un recuerdo. Hoy todos empiezan en el nivel uno: sin oro, sin equipo, sin excusas. Solo el estandarte y la gente a su lado. Así que marchen juntos. Levanten a los nuevos reclutas, llenen cada mazmorra, protejan al Rey, y que cada reino sepa exactamente de quién es el ejército que acaba de llegar.\n\nLlegué a este reino como un extraño, y ustedes me hicieron parte de la corte. La gente más graciosa con la que he jugado, y un equipo del Rey que me trató como familia. Gracias. Me enorgullece marchar con ustedes.\n\nLarga vida al Rey. Larga vida a Olympus.\n\nNovedades de la versión 1.4.0, para la marcha:\n\n- {guild} El censo muestra cada reino del ejército en una sola página, JcJ y JcE, NA y EU: haz clic en el número para ver los totales. Todos los addons coinciden ahora en la cuenta, y no se cuela ningún número de la beta.\n- {crown} El Rey, el Tesorero y el Alto Consejo son reconocidos en los reinos nuevos por la lista firmada.\n- {church} El top tres de la Iglesia y los donantes ahora llegan a todos, no solo a quien estaba conectado en el momento justo, y los marcos los acompañan.\n- {news} Cada cargo recibe una carta del Rey, y cada maestro de hermandad una lista de lo que debe nombrar.\n- {crown} Cada maestro de hermandad tiene 48 horas para verificarse con el Alto Consejo.\n- {gold} La carrera de niveles está en marcha: el primero en llegar a 20, 40 y 60 gana el marco del cometa, para siempre.\n- {star} Olympus ahora encuentra grupos: anuncia el tuyo, apúntate a uno, mira quién busca.\n- {team} Olympus ahora habla inglés, portugués, español, alemán, francés, italiano y ruso.\n- {watch} Un addon anterior a la 1.4.0 ya no encuentra el canal del ejército. Si un amigo ve el censo vacío, dile que actualice.\n- {star} Hecho para multitudes: los mensajes esperan los límites del juego en vez de perderse, y los inicios de sesión ya no inundan al Tesorero.\n- {guild} Fern levantó un salón de hermandad para nosotros. El botón de abajo copia su dirección.\n\nLas puertas están abiertas.",
	LETTER_1_4_0_HEAD = "La Proclamación del Lanzamiento",
	LETTER_1_4_0_LINK = "https://olympus.roachcouncil.com/",
	LETTER_1_4_0_SIGNED = "Vuestro humilde artífice, el desarrollador de Olympus",
	LETTER_1_4_0_TITLE = "Oíd, oíd: las puertas están abiertas",
	LETTER_MARK_BRONZE = "Dragón de bronce:",
	LETTER_MARK_CHURCH = "Iglesia:",
	LETTER_MARK_CRAFT = "Artesanos:",
	LETTER_MARK_CROWN = "Corona:",
