	RB_GM_CHARTER = "Estatutos de la hermandad",
	RB_GM_CHARTER_TEXT = "Propósito, idioma, noches de banda y las clases que buscas, públicos durante siete días. Ayudan a los reclutas a elegir tu hermandad.",
	RB_GM_CHURCH = "Corresponsal de la Iglesia (la pestaña Iglesia)",
