	RB_GM_CHURCHDEPT_JOB = "El contacto de tu hermandad con la Iglesia: trae jugadores nuevos y ayuda a mantener llena la hermandad.",
	RB_GM_CHURCHDEPT_SHOWS = "El escudo de la Iglesia Misionera en su retrato y junto a su nombre.",
	RB_GM_CHURCHDEPT_UNLOCKS = "El título y la sala del departamento. La sala y los números propios de la Iglesia vienen con la línea siguiente.",
	RB_GM_CHURCH_JOB = "Responde ante el Jefe de la Iglesia por mantener llena tu hermandad. Nombra a la misma persona que arriba.",
