	RB_GM_CHURCH_UNLOCKS = "La sala de la Iglesia, los números de la pestaña Iglesia y registrar a los reclutas que trajo.",
	RB_GM_CLOSE = "Una regla: tu poder termina en la puerta de tu hermandad. Dentro, úsalo bien.\n\nAhora ve a construir algo. ¡Vamos!",
	RB_GM_DONE = "[x] %s",
	RB_GM_GET = "Lo que recibes como maestro de hermandad:\n- Las alas de bronce en tu retrato y la marca de bronce junto a tu nombre.\n- La pestaña Hermandad: esta lista y la página de cada departamento.\n- Llamadas a las armas, reuniones, decretos reales e inspecciones de tabardos para tu hermandad.\n- La Agenda de tu hermandad y encuestas de Vox Populi para tu hermandad.\n- La Guardia para tu hermandad, con tus Capitanes.\n- Las salas Maestros de hermandad, Maestros y legados, Maestro y legados, y Maestro y corresponsales.",
	RB_GM_HERALDRY = "Corresponsal del Departamento de Heráldica",
